    long long ans = LLONG_MAX;
    for (int mask = 0; mask < (1 << N); mask++) {
        int rmax = INT_MIN, rmin = INT_MAX, bmax = INT_MIN, bmin = INT_MAX;
        for (int i = 0; i < N; i++) {
