#include <stdio.h>
#include <stdlib.h>
#include <limits.h>

typedef struct {
    int value;
    int bag;
    int other; // the other value in the same bag
} Ball;

int cmp(const void *a, const void *b) {
    return ((Ball*)a)->value - ((Ball*)b)->value;
}

int min(int a, int b) { return a < b ? a : b; }
int max(int a, int b) { return a > b ? a : b; }

int main() {
    int N;
    scanf("%d", &N);

    Ball balls[2 * N];
    int other_val[2 * N];
    int bag_count[N];
    int total = 0;
    int x, y;

    for (int i = 0; i < N; i++) {
        scanf("%d %d", &x, &y);
        balls[total].value = x;
        balls[total].bag = i;
        balls[total].other = y;
        other_val[total] = y;
        total++;

        balls[total].value = y;
        balls[total].bag = i;
        balls[total].other = x;
        other_val[total] = x;
        total++;

        bag_count[i] = 0;
    }

    qsort(balls, 2 * N, sizeof(Ball), cmp);

    int left = 0, right = 0;
    int unique_bags = 0;
    int freq[N];
    for (int i = 0; i < N; i++) freq[i] = 0;

    long long ans = LLONG_MAX;

    // Sliding window to cover all bags
    while (right < 2 * N) {
        // expand window
        while (right < 2 * N && unique_bags < N) {
            int b = balls[right].bag;
            if (freq[b] == 0) unique_bags++;
            freq[b]++;
            right++;
        }
        if (unique_bags < N) break;

        // shrink from left
        while (unique_bags == N) {
            int b = balls[left].bag;
            freq[b]--;
            if (freq[b] == 0) unique_bags--;
            left++;
        }
        // Now window [left-1, right-1] has all bags exactly
        int L = left - 1;
        int R = right - 1;

        // For this window, try both assignments:
        // We have all numbers in sorted order with bag info.
        // For each bag in window, we have two numbers. 
        // We'll assign the smaller to red, larger to blue for each bag, 
        // then compute spans. But since values repeat across bags, 
        // we need actual min/max per color.

        // Actually we can compute directly from window:
        int min_red = INT_MAX, max_red = INT_MIN;
        int min_blue = INT_MAX, max_blue = INT_MIN;

        // Mark which bags we've seen in this window
        int seen[N];
        for (int i = 0; i < N; i++) seen[i] = 0;

        for (int i = L; i <= R; i++) {
            int b = balls[i].bag;
            if (!seen[b]) {
                seen[b] = 1;
                int v1 = balls[i].value;
                int v2 = balls[i].other;
                int small = v1 < v2 ? v1 : v2;
                int large = v1 > v2 ? v1 : v2;
                min_red = min(min_red, small);
                max_red = max(max_red, small);
                min_blue = min(min_blue, large);
                max_blue = max(max_blue, large);
            }
        }

        long long prod = (long long)(max_red - min_red) * (max_blue - min_blue);
        if (prod < ans) ans = prod;

        // Also try swapping: assign small to blue, large to red
        min_red = INT_MAX; max_red = INT_MIN;
        min_blue = INT_MAX; max_blue = INT_MIN;
        for (int i = 0; i < N; i++) seen[i] = 0;

        for (int i = L; i <= R; i++) {
            int b = balls[i].bag;
            if (!seen[b]) {
                seen[b] = 1;
                int v1 = balls[i].value;
                int v2 = balls[i].other;
                int small = v1 < v2 ? v1 : v2;
                int large = v1 > v2 ? v1 : v2;
                min_blue = min(min_blue, small);
                max_blue = max(max_blue, small);
                min_red = min(min_red, large);
                max_red = max(max_red, large);
            }
        }

        prod = (long long)(max_red - min_red) * (max_blue - min_blue);
        if (prod < ans) ans = prod;
    }

    printf("%lld\n", ans);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>

typedef long long ll;

typedef struct {
    ll x, y;
} Bag;

typedef struct {
    ll v;
    int bag;
    int side; // 0 -> x, 1 -> y
} Ball;

static int cmp_ll(const void *a, const void *b) {
    ll x = *(const ll *)a;
    ll y = *(const ll *)b;
    if (x < y) return -1;
    if (x > y) return 1;
    return 0;
}

static int cmp_ball(const void *a, const void *b) {
    const Ball *p = (const Ball *)a;
    const Ball *q = (const Ball *)b;
    if (p->v < q->v) return -1;
    if (p->v > q->v) return 1;
    return 0;
}

static ll minll(ll a, ll b) { return a < b ? a : b; }
static ll maxll(ll a, ll b) { return a > b ? a : b; }

int main(void) {
    int N;
    if (scanf("%d", &N) != 1) return 0;

    Bag *bags = (Bag *)malloc(sizeof(Bag) * N);
    Ball *balls = (Ball *)malloc(sizeof(Ball) * 2 * N);
    ll *mins = (ll *)malloc(sizeof(ll) * N);
    ll *maxs = (ll *)malloc(sizeof(ll) * N);

    for (int i = 0; i < N; i++) {
        ll x, y;
        scanf("%lld %lld", &x, &y);
        bags[i].x = x;
        bags[i].y = y;
        mins[i] = minll(x, y);
        maxs[i] = maxll(x, y);

        balls[2 * i].v = x;
        balls[2 * i].bag = i;
        balls[2 * i].side = 0;

        balls[2 * i + 1].v = y;
        balls[2 * i + 1].bag = i;
        balls[2 * i + 1].side = 1;
    }

    qsort(mins, N, sizeof(ll), cmp_ll);
    qsort(maxs, N, sizeof(ll), cmp_ll);
    qsort(balls, 2 * N, sizeof(Ball), cmp_ball);

    ll ans = (maxs[N - 1] - mins[0]) * (maxs[N - 1] - mins[0]);

    // Case 1:
    // One color gets all mins, the other gets all maxs.
    // Then answer is (max(mins)-min(mins)) * (max(maxs)-min(maxs)).
    ll r1 = mins[N - 1] - mins[0];
    ll b1 = maxs[N - 1] - maxs[0];
    ans = minll(ans, r1 * b1);

    // Case 2:
    // The two color intervals overlap.
    // Then the union width determines one side, and we minimize the other side
    // by choosing two boundary balls belonging to different bags.
    //
    // Let total width = max(all) - min(all) = balls[2N-1].v - balls[0].v.
    // We need the smallest gap [balls[l], balls[r]] such that these two balls
    // come from different bags. That gap can be the smaller interval width.
    ll total = balls[2 * N - 1].v - balls[0].v;
    ll bestGap = (1LL << 62);

    // Since only adjacent candidates around each bag matter, it is enough to
    // check neighboring balls from different bags in sorted order.
    for (int i = 0; i + 1 < 2 * N; i++) {
        if (balls[i].bag != balls[i + 1].bag) {
            ll gap = balls[i + 1].v - balls[i].v;
            if (gap < bestGap) bestGap = gap;
        }
    }

    // Also need to consider taking one boundary from the leftmost ball and another
    // from some later different bag, or similarly near the rightmost side.
    // In fact adjacent different-bag pair suffices for minimum possible interval.
    ans = minll(ans, total * bestGap);

    printf("%lld\n", ans);

    free(bags);
    free(balls);
    free(mins);
    free(maxs);
    return 0;
}

