import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        int N = Integer.parseInt(br.readLine());
        int[][] bags = new int[N][2];
        for (int i = 0; i < N; i++) {
            StringTokenizer st = new StringTokenizer(br.readLine());
            bags[i][0] = Integer.parseInt(st.nextToken());
            bags[i][1] = Integer.parseInt(st.nextToken());
        }

        // We'll try both color assignments implicitly.
        // For each bag, we can decide which ball is red and which is blue.
        // Equivalent to: we will assign one ball to red set, other to blue.
        // Minimize (maxR - minR) * (maxB - minB).

        // Approach: try all possible splits based on sorting by one value.

        long answer = Long.MAX_VALUE;
        // Try 4 orientations in case of swapping definition of red/blue
        for (int swap = 0; swap < 2; swap++) {
            // Normalize each bag so that first element <= second element? Not necessary.
            // We'll treat each bag as (a,b) and try both assignments via a technique:
            // Sort by one value, then keep track of the other.

            // We'll create events: each bag gives two possible (value, bagID) for red, 
            // and the other goes to blue.
            // Use multiset for blue values.

            int[][] sorted = new int[N][2];
            for (int i = 0; i < N; i++) {
                sorted[i][0] = bags[i][0];
                sorted[i][1] = bags[i][1];
                if (swap == 1) {
                    int tmp = sorted[i][0];
                    sorted[i][0] = sorted[i][1];
                    sorted[i][1] = tmp;
                }
            }

            // Try assigning the smaller of each pair to red, larger to blue.
            // Then swap roles.

            // Case 1: For each bag, red = min(x_i, y_i), blue = max(x_i, y_i)
            long val1 = computeMinProduct(N, sorted, false);
            // Case 2: red = max, blue = min
            long val2 = computeMinProduct(N, sorted, true);
            answer = Math.min(answer, Math.min(val1, val2));
        }

        System.out.println(answer);
    }

    static long computeMinProduct(int N, int[][] bags, boolean swapRole) {
        // We'll create list of (redValue, blueValue) per bag.
        int[][] pairs = new int[N][2];
        for (int i = 0; i < N; i++) {
            int a = bags[i][0];
            int b = bags[i][1];
            if (!swapRole) {
                pairs[i][0] = Math.min(a, b);
                pairs[i][1] = Math.max(a, b);
            } else {
                pairs[i][0] = Math.max(a, b);
                pairs[i][1] = Math.min(a, b);
            }
        }

        // Sort by red value
        Arrays.sort(pairs, (p, q) -> Integer.compare(p[0], q[0]));

        // Multiset for blue values
        TreeMap<Integer, Integer> blueMap = new TreeMap<>();
        for (int i = 0; i < N; i++) {
            blueMap.put(pairs[i][1], blueMap.getOrDefault(pairs[i][1], 0) + 1);
        }

        long ans = Long.MAX_VALUE;
        int minRed = pairs[0][0];
        int maxRed = pairs[N-1][0];

        // We'll try to remove from red the smallest red values one by one,
        // moving them to blue set by swapping assignment? Wait, we already fixed assignment.
        // Actually to find minimum we need to consider swapping assignments per bag.
        // So we'll try: for each possible split point in sorted by red, 
        // we decide that for some prefix we swap the assignment (so those become blue=their original red, 
        // red=their original blue).
        // This corresponds to: initially all assigned as above.
        // Then we iterate i from 0..N-1, for each we "swap" the i-th bag's colors.
        // Keep multiset for blue values after possible swaps.

        // Reset: start with no swaps.
        // We'll simulate moving smallest red to become blue.

        TreeMap<Integer, Integer> currentBlue = new TreeMap<>(blueMap);
        int curMinRed = pairs[0][0];
        int curMaxRed = pairs[N-1][0];

        // Also maintain current blue min/max from currentBlue
        int curMinBlue = currentBlue.firstKey();
        int curMaxBlue = currentBlue.lastKey();
        ans = Math.min(ans, (long)(curMaxRed - curMinRed) * (curMaxBlue - curMinBlue));

        for (int i = 0; i < N; i++) {
            // Swap bag i: its red becomes blue, its blue becomes red.
            int oldRed = pairs[i][0];
            int oldBlue = pairs[i][1];

            // Remove oldBlue from blue set
            removeOne(currentBlue, oldBlue);
            // Add oldRed to blue set
            currentBlue.put(oldRed, currentBlue.getOrDefault(oldRed, 0) + 1);

            // Now update red set: since we swapped, this bag now contributes oldBlue to red
            // But red set is just based on current assignments; we can recompute min/max red from the 
            // first i+1 swapped ones and the rest unswapped.
            // Actually easier: after swapping first i+1 bags, red values are:
            // For j <= i: pairs[j][1] (original blue becomes red)
            // For j > i: pairs[j][0] (original red stays red)

            // We can compute minRed and maxRed incrementally.
            if (i == 0) {
                curMinRed = pairs[0][1];
                curMaxRed = pairs[0][1];
            } else {
                curMinRed = Math.min(curMinRed, pairs[i][1]);
                curMaxRed = Math.max(curMaxRed, pairs[i][1]);
            }
            // Also consider the unswapped part's red values. 
            // The unswapped part's min is pairs[i+1][0] (if exists)
            // We need overall min among: swapped part (pairs[0..i][1]) and unswapped part (pairs[i+1..N-1][0])
            int overallMinRed = curMinRed;
            int overallMaxRed = curMaxRed;
            if (i + 1 < N) {
                overallMinRed = Math.min(overallMinRed, pairs[i+1][0]);
                overallMaxRed = Math.max(overallMaxRed, pairs[N-1][0]);
            }

            if (!currentBlue.isEmpty()) {
                curMinBlue = currentBlue.firstKey();
                curMaxBlue = currentBlue.lastKey();
                ans = Math.min(ans, (long)(overallMaxRed - overallMinRed) * (curMaxBlue - curMinBlue));
            }
        }

        return ans;
    }

    static void removeOne(TreeMap<Integer, Integer> map, int key) {
        int count = map.get(key);
        if (count == 1) {
            map.remove(key);
        } else {
            map.put(key, count - 1);
        }
    }
}

import java.io.*;
import java.util.*;

public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        long nextLong() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);
            long sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            long val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }

        int nextInt() throws IOException {
            return (int) nextLong();
        }
    }

    static class Pair {
        long a, b;
        Pair(long a, long b) {
            this.a = a;
            this.b = b;
        }
    }

    static class Event {
        long v;
        int bag;
        int side; // 0 or 1
        Event(long v, int bag, int side) {
            this.v = v;
            this.bag = bag;
            this.side = side;
        }
    }

    static class MultiSet {
        TreeMap<Long, Integer> map = new TreeMap<>();
        int size = 0;

        void add(long x) {
            map.put(x, map.getOrDefault(x, 0) + 1);
            size++;
        }

        void remove(long x) {
            int c = map.get(x);
            if (c == 1) map.remove(x);
            else map.put(x, c - 1);
            size--;
        }

        long min() {
            return map.firstKey();
        }

        long max() {
            return map.lastKey();
        }

        boolean isEmpty() {
            return size == 0;
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();
        int N = fs.nextInt();
        Pair[] bags = new Pair[N];
        Event[] ev = new Event[2 * N];

        for (int i = 0; i < N; i++) {
            long x = fs.nextLong();
            long y = fs.nextLong();
            bags[i] = new Pair(x, y);
            ev[2 * i] = new Event(x, i, 0);
            ev[2 * i + 1] = new Event(y, i, 1);
        }

        Arrays.sort(ev, Comparator.comparingLong(e -> e.v));

        // For each bag:
        // state 0: both endpoints on right side of current cut
        // state 1: one on left, one on right
        // state 2: both on left
        int[] cntLeft = new int[N];

        // Mixed bags contribute one forced red and one forced blue:
        // their two values are exactly the pair values.
        MultiSet mixedVals = new MultiSet();

        // For bags entirely on one side, we may choose orientation freely.
        // To make red interval feasible for a chosen [L, U], a uniform bag can contribute
        // red = min(a,b) or max(a,b). We maintain all mins and maxs.
        MultiSet uniformMins = new MultiSet();
        MultiSet uniformMaxs = new MultiSet();

        for (int i = 0; i < N; i++) {
            long a = bags[i].a, b = bags[i].b;
            uniformMins.add(Math.min(a, b));
            uniformMaxs.add(Math.max(a, b));
        }

        long ans = Long.MAX_VALUE;

        // Consider red interval [ev[l].v, ev[r].v].
        // Sweep l from left to right, and for each l expand r minimally so that
        // every mixed bag can place its forced red inside the interval and every
        // uniform bag can choose one endpoint inside the interval.
        int r = -1;

        for (int l = 0; l < 2 * N; l++) {
            long L = ev[l].v;

            if (r < l - 1) r = l - 1;

            while (true) {
                long U = (r >= l ? ev[r].v : L - 1);

                boolean okMixed = mixedVals.isEmpty() || (mixedVals.min() >= L && mixedVals.max() <= U);
                boolean okUniform = uniformMins.isEmpty() || !(uniformMaxs.max() < L || uniformMins.min() > U);

                if (okMixed && okUniform) break;
                r++;
                if (r >= 2 * N) break;
            }

            if (r >= 2 * N) break;

            long U = ev[r].v;
            long redWidth = U - L;

            // Given red interval [L,U], compute minimal possible blue width.
            // Mixed bags force the opposite endpoint to blue, but since mixedVals contains both endpoints
            // of mixed bags, blue forced values are the same multiset as mixedVals.
            // Uniform bags can choose the endpoint outside red as blue.
            //
            // For a uniform bag:
            // - if both endpoints in [L,U], blue can be either endpoint
            // - if exactly one endpoint in [L,U], blue is forced to the other
            //
            // The global minimal blue interval containing one blue from each bag
            // can be shown to be:
            // max(max forced blue, max among bags' smaller possible blue choices as needed)
            // minus
            // min(min forced blue, min among bags' larger possible blue choices as needed)
            //
            // Easier formulation:
            // Since each bag contributes the complementary endpoint, the set of blue values
            // is exactly one value from each pair, opposite to red choice.
            // This is symmetric to red. Hence for fixed red interval [L,U], the possible blue
            // values per bag are:
            // bag values outside [L,U] if exactly one inside, both values if both inside, impossible if both outside.
            //
            // So blue min is minimized by choosing smallest available blue per bag,
            // blue max is minimized only globally. We can derive exact min/max:
            long blueMin = Long.MAX_VALUE;
            long blueMax = Long.MIN_VALUE;

            for (int i = 0; i < N; i++) {
                long a = bags[i].a, b = bags[i].b;
                boolean ina = (L <= a && a <= U);
                boolean inb = (L <= b && b <= U);

                long low, high;
                if (ina && inb) {
                    low = Math.min(a, b);
                    high = Math.max(a, b);
                } else if (ina) {
                    low = high = b;
                } else if (inb) {
                    low = high = a;
                } else {
                    low = 1;
                    high = 0; // impossible, but should not occur due to feasibility
                }

                blueMin = Math.min(blueMin, low);
                blueMax = Math.max(blueMax, high);
            }

            long blueWidth = blueMax - blueMin;
            ans = Math.min(ans, redWidth * blueWidth);

            // move l forward: update structures by transferring ev[l] to the left side
            Event e = ev[l];
            int i = e.bag;
            long a = bags[i].a, b = bags[i].b;

            int before = cntLeft[i];
            int after = before + 1;
            cntLeft[i] = after;

            if (before == 0) {
                // uniform -> mixed
                uniformMins.remove(Math.min(a, b));
                uniformMaxs.remove(Math.max(a, b));
                mixedVals.add(a);
                mixedVals.add(b);
            } else if (before == 1) {
                // mixed -> uniform
                mixedVals.remove(a);
                mixedVals.remove(b);
                uniformMins.add(Math.min(a, b));
                uniformMaxs.add(Math.max(a, b));
            }
        }

        System.out.println(ans);
    }
}

#include <bits/stdc++.h>
using namespace std;
using int64 = long long;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;
    vector<pair<int,int>> bags(n);
    vector<int> all;
    for (int i = 0; i < n; i++) {
        cin >> bags[i].first >> bags[i].second;
        all.push_back(bags[i].first);
        all.push_back(bags[i].second);
    }
    sort(all.begin(), all.end());
    all.erase(unique(all.begin(), all.end()), all.end());
    int m = all.size();

    const int64 INF = 1e18;
    int64 ans = INF;

    // Try all pairs as (Rmin, Rmax)
    for (int li = 0; li < m; li++) {
        for (int ri = li; ri < m; ri++) {
            int rmin = all[li];
            int rmax = all[ri];
            bool ok = true;
            int bmin = INT_MAX, bmax = INT_MIN;
            for (auto &bag : bags) {
                int a = bag.first, b = bag.second;
                // check if we can assign one to red within [rmin, rmax]
                bool a_in = (a >= rmin && a <= rmax);
                bool b_in = (b >= rmin && b <= rmax);
                if (!a_in && !b_in) {
                    ok = false;
                    break;
                }
                // choose the one that goes to blue to minimize range
                int red_val, blue_val;
                if (a_in && b_in) {
                    // both can be red; put the larger one to blue to maybe reduce range
