    int N;
    cin >> N;
    vector<pair<ll,ll>> a(N);
    vector<ll> all;
    all.reserve(2 * N);

    for (int i = 0; i < N; ++i) {
        ll x, y;
        cin >> x >> y;
        a[i] = {x, y};
        all.push_back(x);
        all.push_back(y);
    }

    sort(all.begin(), all.end());
    all.erase(unique(all.begin(), all.end()), all.end());

    ll ans = (1LL << 62);

    int M = (int)all.size();

    // Enumerate R_min = all[i], R_max = all[j].
    // For each bag:
    // - if both values are inside [L, R], either coloring works -> blue contributes one of the two values
    // - if exactly one value is inside, that one must be red, the other blue
    // - if none are inside, impossible
    //
    // Then blue values form intervals [min(outside-forced/choice), max(...)].
    // We need the minimum possible blue range.
    for (int i = 0; i < M; ++i) {
        for (int j = i; j < M; ++j) {
            ll L = all[i], R = all[j];

            bool ok = true;
            ll forcedMin = (1LL << 62), forcedMax = -(1LL << 62);
            vector<pair<ll,ll>> flex; // possible blue values from bags fully inside [L,R]

            for (int k = 0; k < N; ++k) {
                ll x = a[k].first, y = a[k].second;
                bool inx = (L <= x && x <= R);
                bool iny = (L <= y && y <= R);

                if (!inx && !iny) {
                    ok = false;
                    break;
                } else if (inx && iny) {
                    ll p = min(x, y), q = max(x, y);
                    flex.push_back({p, q});
                } else {
                    ll b = inx ? y : x; // outside one must be blue
                    forcedMin = min(forcedMin, b);
                    forcedMax = max(forcedMax, b);
                }
            }

            if (!ok) continue;

            ll blueRange;

            if (forcedMax == -(1LL << 62)) {
                // No forced blue values. Need minimum range choosing one endpoint from each flex interval.
                // For intervals [l_i, r_i], minimum possible range is:
                // max(0, max l_i - min r_i)
                ll maxL = -(1LL << 62), minR = (1LL << 62);
                for (auto &pr : flex) {
                    maxL = max(maxL, pr.first);
                    minR = min(minR, pr.second);
                }
                blueRange = max(0LL, maxL - minR);
            } else {
                // Forced blue range already [forcedMin, forcedMax].
                // Any flex bag can choose one endpoint; if possible choose inside this range, else expands it minimally.
                ll mn = forcedMin, mx = forcedMax;
                for (auto &pr : flex) {
                    ll p = pr.first, q = pr.second;
                    if (q < mn) mn = q;
                    else if (p > mx) mx = p;
                    // otherwise can choose a value within [mn, mx], no change
                }
                blueRange = mx - mn;
            }

            ll redRange = R - L;
            ans = min(ans, redRange * blueRange);
        }
    }

    cout << ans << '\n';
    return 0;
